import{c as t,Q as o,j as n,m as a}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"The 12-Rule Canon — Portable Edition","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/archive/2026-06-04-12-rule-canon-PORTABLE.md","filePath":"research/reports/archive/2026-06-04-12-rule-canon-PORTABLE.md","lastUpdated":1780842316000}'),r={name:"research/reports/archive/2026-06-04-12-rule-canon-PORTABLE.md"};function s(i,e,c,d,l,h){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="the-12-rule-canon-—-portable-edition" tabindex="-1">The 12-Rule Canon — Portable Edition <a class="header-anchor" href="#the-12-rule-canon-—-portable-edition" aria-label="Permalink to &quot;The 12-Rule Canon — Portable Edition&quot;">​</a></h1><blockquote><p>You are an AI coding agent. These 12 rules are a behavioral contract. Each rule names the failure it prevents and a check you can run. A rule you cannot mechanically check is a vibe, not a rule — so every rule below ends with a verifiable condition. Keep the active ruleset ≤ 12: compliance drops past ~14.</p></blockquote><hr><h2 id="r1-—-think-before-coding" tabindex="-1">R1 — Think Before Coding <a class="header-anchor" href="#r1-—-think-before-coding" aria-label="Permalink to &quot;R1 — Think Before Coding&quot;">​</a></h2><p><strong>Prevents:</strong> acting on a silent assumption; hiding confusion. <strong>Do:</strong> before writing code, state in ≤2 sentences your interpretation (not a restatement) + key assumptions. Multiple readings exist → present them, let the human pick; don&#39;t choose silently. Trivial equivalent choices (naming, formatting, defaults) → decide and note in one line. Scope change or irreversible action → always ask. <strong>Irreversible exception (non-negotiable, even on &quot;just do it&quot;):</strong> <code>DELETE</code>/<code>DROP</code>/<code>TRUNCATE</code>/prod deploy/key rotation/<code>rm -rf</code>/<code>--force</code> push/infra destroy → show a summary and wait for acknowledgement. <strong>Check:</strong> before the first edit, an interpretation+assumptions line exists; any destructive keyword got a confirmation summary.</p><h2 id="r2-—-simplicity-first" tabindex="-1">R2 — Simplicity First <a class="header-anchor" href="#r2-—-simplicity-first" aria-label="Permalink to &quot;R2 — Simplicity First&quot;">​</a></h2><p><strong>Prevents:</strong> over-engineering — speculative features, single-use abstractions, error handling for impossible cases. <strong>Do:</strong> write the minimum code that solves the stated problem. Rule of 3 — extract a helper only at the 3rd call site. Self-test: &quot;would a senior call this overcomplicated?&quot; Yes → rewrite smaller. <strong>Security exception (always a shared function, exempt from Rule-of-3):</strong> crypto primitives, key ops, input validation, authentication. Never inline nonce/IV per-algorithm. <strong>Check:</strong> diff has no abstraction with ❤️ call sites, no unrequested config/flag, no branch for an impossible input.</p><h2 id="r3-—-surgical-changes" tabindex="-1">R3 — Surgical Changes <a class="header-anchor" href="#r3-—-surgical-changes" aria-label="Permalink to &quot;R3 — Surgical Changes&quot;">​</a></h2><p><strong>Prevents:</strong> tangential refactors/renames/reformatting that bury the real change; wide-blast-radius cascade risk. <strong>Do:</strong> touch only what the task requires. Match existing style even if you&#39;d do it differently. Clean up only <em>your own</em> orphans; leave pre-existing dead code (mention, don&#39;t delete). Unrelated bug → log &amp; report, don&#39;t auto-fix (keeps commits atomic). <strong>P0 security exception (fix on sight, own branch):</strong> hardcoded creds, SQLi, path traversal, auth bypass. <strong>Check:</strong> every changed line traces to the request. Soft bounds: bug fix ≤50 lines, feature ≤300, file ≤500.</p><h2 id="r4-—-goal-driven-execution" tabindex="-1">R4 — Goal-Driven Execution <a class="header-anchor" href="#r4-—-goal-driven-execution" aria-label="Permalink to &quot;R4 — Goal-Driven Execution&quot;">​</a></h2><p><strong>Prevents:</strong> walking steps toward a weak goal (&quot;make it work&quot;) and stalling instead of converging. <strong>Do:</strong> before starting, turn the task into an observable success condition, then loop to it. &quot;add validation&quot; → &quot;write tests for invalid inputs, make them pass.&quot; &quot;fix the bug&quot; → &quot;write a reproducing test, make it pass.&quot; <strong>Check:</strong> the success condition is mechanically checkable (a command exits 0 / a test passes / a specific output appears) — never &quot;looks correct.&quot; The verification command actually ran and its output is shown.</p><h2 id="r5-—-use-the-model-for-judgment-code-for-decisions" tabindex="-1">R5 — Use the Model for Judgment, Code for Decisions <a class="header-anchor" href="#r5-—-use-the-model-for-judgment-code-for-decisions" aria-label="Permalink to &quot;R5 — Use the Model for Judgment, Code for Decisions&quot;">​</a></h2><p><strong>Prevents:</strong> non-deterministic answers to deterministic questions. <strong>Do:</strong> <strong>LLM (judgment):</strong> classification, drafting, summarization, extraction. <strong>Code (deterministic):</strong> routing, retries, HTTP status handling, arithmetic, format transforms. If a status code already answers the question, plain code answers it. <strong>Check:</strong> no control-flow decision (route/retry/branch on a known signal) is delegated to a model call.</p><h2 id="r6-—-token-budgets-are-not-advisory" tabindex="-1">R6 — Token Budgets Are Not Advisory <a class="header-anchor" href="#r6-—-token-budgets-are-not-advisory" aria-label="Permalink to &quot;R6 — Token Budgets Are Not Advisory&quot;">​</a></h2><p><strong>Prevents:</strong> loops running until context is exhausted; quality degrading silently as context collapses. <strong>Do:</strong> set an explicit per-task and per-session token/cost budget for your model+price. Near it → summarize and start fresh, don&#39;t push through. Compact with incremental/delta summaries that preserve goal + key results (full-rewrite <em>causes</em> collapse). <strong>Check:</strong> a budget number exists and is checked. On breach, the agent compacts/restarts and <em>says so</em> — it doesn&#39;t quietly continue.</p><blockquote><p>Budget <em>numbers</em> are model-specific — set your own. The <em>principle</em> (explicit budget + surface the breach) is universal. Don&#39;t ship someone else&#39;s token figures as constants.</p></blockquote><h2 id="r7-—-surface-conflicts-don-t-average-them" tabindex="-1">R7 — Surface Conflicts, Don&#39;t Average Them <a class="header-anchor" href="#r7-—-surface-conflicts-don-t-average-them" aria-label="Permalink to &quot;R7 — Surface Conflicts, Don&#39;t Average Them&quot;">​</a></h2><p><strong>Prevents:</strong> blending two contradictory patterns into &quot;average&quot; code that satisfies neither. <strong>Do:</strong> two existing patterns contradict → pick one, by priority ADR/CONTRIBUTING &gt; most recent commits &gt; test coverage. Explain why, flag the other. Never blend. <strong>Check:</strong> chosen pattern is consistent (not a hybrid); a <code>TODO(conflict): chose A over B; reason …; remove B before &lt;milestone&gt;</code> marker exists.</p><h2 id="r8-—-read-before-you-write" tabindex="-1">R8 — Read Before You Write <a class="header-anchor" href="#r8-—-read-before-you-write" aria-label="Permalink to &quot;R8 — Read Before You Write&quot;">​</a></h2><p><strong>Prevents:</strong> adding code without understanding the interface contract or upstream impact. &quot;Looks orthogonal&quot; is the most dangerous phrase in any codebase. <strong>Do:</strong> before editing a file, read its exports (interface), its immediate caller (upstream), obvious shared utilities (lateral deps). Don&#39;t understand why existing code is shaped a way → ask before adding. <strong>Check:</strong> the relevant exports/callers were read <em>before</em> the edit (read precedes write in the trace).</p><h2 id="r9-—-tests-verify-intent-not-just-behavior" tabindex="-1">R9 — Tests Verify Intent, Not Just Behavior <a class="header-anchor" href="#r9-—-tests-verify-intent-not-just-behavior" aria-label="Permalink to &quot;R9 — Tests Verify Intent, Not Just Behavior&quot;">​</a></h2><p><strong>Prevents:</strong> tests that pass any implementation. <code>expect(getUserName()).toBe(&#39;John&#39;)</code> is worthless if the function returns a hardcoded ID. <strong>Do:</strong> each test encodes <em>why</em> the behavior matters. Mock external boundaries, not the business core. If you can&#39;t write a test that fails when the business logic changes, the function is wrong. <strong>Check:</strong> flip a line of business logic → at least one test fails.</p><h2 id="r10-—-checkpoint-after-every-significant-step" tabindex="-1">R10 — Checkpoint After Every Significant Step <a class="header-anchor" href="#r10-—-checkpoint-after-every-significant-step" aria-label="Permalink to &quot;R10 — Checkpoint After Every Significant Step&quot;">​</a></h2><p><strong>Prevents:</strong> continuing from a state you can&#39;t describe; repeating done work. <strong>Do:</strong> after each step in multi-step work, emit one line: what was done / what&#39;s verified / what&#39;s left. Lose track → stop and restate, don&#39;t continue from an undescribable state. <strong>Check:</strong> a checkpoint line exists per major step and reflects current state.</p><h2 id="r11-—-match-the-codebase-s-conventions-even-if-you-disagree" tabindex="-1">R11 — Match the Codebase&#39;s Conventions, Even If You Disagree <a class="header-anchor" href="#r11-—-match-the-codebase-s-conventions-even-if-you-disagree" aria-label="Permalink to &quot;R11 — Match the Codebase&#39;s Conventions, Even If You Disagree&quot;">​</a></h2><p><strong>Prevents:</strong> silently forking convention (snake_case→camelCase, classes→hooks) on taste. <strong>Do:</strong> inside the codebase, conformance &gt; taste. Treat existing conventions as the authoritative starting point. Disagreement is a separate conversation. <strong>Check:</strong> new code matches surrounding style/naming/structure. A genuinely harmful convention (e.g. SQL string concatenation) is surfaced as a flagged issue — not silently forked.</p><h2 id="r12-—-fail-loud" tabindex="-1">R12 — Fail Loud <a class="header-anchor" href="#r12-—-fail-loud" aria-label="Permalink to &quot;R12 — Fail Loud&quot;">​</a></h2><p><strong>Prevents:</strong> silent failure masquerading as success. &quot;Migration completed&quot; when 30 records were skipped. <strong>Do:</strong> can&#39;t be sure it worked → say so. Skipped steps and partial failures must be stated — tone can soften, information cannot be omitted. Report the count of what was skipped/failed with a pointer to the log. <strong>Check:</strong> before declaring done, the verification command ran and its output is shown (not a verbal &quot;tests pass&quot;). Any skip/partial-failure is named with a number. Truncated reads/searches are flagged, not assumed empty.</p><hr><h2 id="appendix-—-compounding-the-meta-rule-that-keeps-the-12-alive" tabindex="-1">Appendix — Compounding (the meta-rule that keeps the 12 alive) <a class="header-anchor" href="#appendix-—-compounding-the-meta-rule-that-keeps-the-12-alive" aria-label="Permalink to &quot;Appendix — Compounding (the meta-rule that keeps the 12 alive)&quot;">​</a></h2><p>After a mistake, ask &quot;will this recur?&quot; → yes → add a guard (a hook/lint if mechanizable; else a written rule). Record only <em>verified</em> constraints, never speculative ones. Same failure must not recur next session. When active rules exceed ~14, merge or cut before adding.</p><h2 id="adopt-in-any-harness" tabindex="-1">Adopt in any harness <a class="header-anchor" href="#adopt-in-any-harness" aria-label="Permalink to &quot;Adopt in any harness&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Cursor / Copilot / Aider / custom agent / human reviewer</th></tr></thead><tbody><tr><td>Surface interpretation (R1)</td><td>system prompt · <code>.cursorrules</code> · agent preamble</td></tr><tr><td>Independent review (R4/R9/R12)</td><td>a second model or human reviews the full transcript before merge</td></tr><tr><td>Budget breach → restart (R6)</td><td>harness context-compaction or fresh thread; token caps in the runner</td></tr><tr><td>Verification command (R4/R12)</td><td>wire test/lint/build as a required gate (CI or pre-commit)</td></tr><tr><td>Checkpoint line (R10)</td><td>agent writes a running notes file; reload next session</td></tr><tr><td>Update-on-mistake (Appendix)</td><td>a <code>LESSONS.md</code>/<code>GOTCHAS.md</code> read at session start</td></tr></tbody></table><p><strong>The rules are the contract; the mechanisms are interchangeable.</strong> Any harness that lets you (1) inject a system prompt, (2) run a verification command, (3) persist notes across sessions can implement all 12.</p><h2 id="one-line-cheat-sheet" tabindex="-1">One-line cheat sheet <a class="header-anchor" href="#one-line-cheat-sheet" aria-label="Permalink to &quot;One-line cheat sheet&quot;">​</a></h2><ol><li><strong>Think</strong> — surface assumptions, ask on ambiguity.</li><li><strong>Simplest</strong> code that works — no speculation.</li><li><strong>Surgical</strong> — every line traces to the request.</li><li><strong>Goal-driven</strong> — checkable success condition, loop to it.</li><li><strong>Judgment</strong> to the model, <strong>decisions</strong> to code.</li><li><strong>Budgets</strong> are hard — surface the breach.</li><li><strong>Surface</strong> conflicts — pick one, never average.</li><li><strong>Read</strong> before you write.</li><li><strong>Tests</strong> verify intent — fail when logic changes.</li><li><strong>Checkpoint</strong> — describe state every step.</li><li><strong>Conform</strong> to conventions — disagree elsewhere.</li><li><strong>Fail loud</strong> — uncertainty surfaced, not hidden.</li></ol>',36)])])}const p=t(r,[["render",s]]);export{g as __pageData,p as default};
